  async importVoices(files){const results=[];for(const file of files.slice(0,20)){const ext=path.extname(file).slice(1).toLowerCase();if(!['wav','mp3','ogg'].includes(ext)||(await stat(file)).size>8*1024*1024)throw Error('仅支持8MB以内 WAV/MP3/OGG');const bytes=await readFile(file),magic=bytes.subarray(0,12);if(!(ext==='wav'&&magic.subarray(0,4).toString()==='RIFF'&&magic.subarray(8,12).toString()==='WAVE'||ext==='ogg'&&magic.subarray(0,4).toString()==='OggS'||ext==='mp3'&&(magic.subarray(0,3).toString()==='ID3'||magic[0]===255&&(magic[1]&224)===224)))throw Error('音频格式与扩展名不匹配');await this.store.change(async()=>{const rows=await this.store.voices();if(rows.length>=50)throw Error('最多50条语音');const id=randomUUID(),name=id+'.'+ext;await mkdir(path.join(this.store.root,'voices'),{recursive:true});await writeFile(path.join(this.store.root,'voices',name),bytes,{flag:'wx',mode:0o600});rows.push({id,file:name,name:path.basename(file).slice(0,80),meaning:'',enabled:false,bytes:bytes.length});await this.store.write('voices.json',rows);results.push(id);});}return{imported:results.length};}
